What does the following program print out?
class UFO:
    def __init__(self, name="SP24"):
        self.name = name
        print(self.name, "was just born.")

    def say_hi(self):
        print("Hello world! I am", self.name)

    def __del__(self):
        print("My mission is completed.")

ufo = UFO("SP25")
ufo.say_hi()

What will be the output of the following code?
class MyClass:
    def __init__(self, value):
        self.value = value

    def __eq__(self, other):
        return self.value != other.value

obj1 = MyClass(10)
obj2 = MyClass(10)
print(obj1 == obj2)

